/**
 * Parses a caught error (from an API call, etc.) and returns a readable string.
 */
const getApiErrorMessage = (error: unknown): string => {
    if (error == null) return "An unknown error occurred.";
    if (typeof error === 'string') return error;
    if (error instanceof Error) return error.message;
    if (typeof error === 'object') {
        const errorObj = error as Record<string, unknown>;
        if (typeof errorObj.details === 'string' && errorObj.details) return errorObj.details;
        if (typeof errorObj.message === 'string' && errorObj.message) return errorObj.message;
    }
    try {
        return JSON.stringify(error, null, 2);
    } catch (e) {
        return "An un-stringifiable error object was received. Check the console for more details.";
    }
};

const parseMonth = (monthStr: string | undefined): number | null => {
    if (!monthStr) return null;
    const trimmedLower = monthStr.toLowerCase().trim();
    if (trimmedLower === 'na') return null;

    const monthNum = parseInt(trimmedLower, 10);
    if (!isNaN(monthNum) && monthNum >= 1 && monthNum <= 12) return monthNum;

    const monthMap: { [key: string]: number } = {
        'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
        'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12,
    };
    return monthMap[trimmedLower.substring(0, 3)] || null;
}

const parseDateToYyyyMmDd = (dateStr: string | undefined): string | null => {
    if (!dateStr || dateStr.trim() === '') return null;
    // Try parsing as YYYY-MM-DD
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
        const d = new Date(dateStr);
        if (!isNaN(d.getTime())) return dateStr;
    }
    // Try parsing as M/D/YYYY
    const parts = dateStr.split('/');
    if (parts.length === 3) {
        let [month, day, year] = parts.map(p => parseInt(p, 10));
        if (!isNaN(month) && !isNaN(day) && !isNaN(year)) {
             // Handle two-digit year
            if (year < 100) {
                year += 2000;
            }
            if (month >= 1 && month <= 12 && day >= 1 && day <= 31 && year > 1900) {
                return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
            }
        }
    }
    return null; // Invalid or unhandled format
};


