interface AnalyticsDashboardProps {
    projects: Project[];
    milestones: Milestone[];
    teams: Lookup[];
    customers: Lookup[];
    projectManagers: User[];
    language: Language;
    currentUser?: User;
    onUpdateMilestone: (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>) => Promise<void>;
}

const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = (props) => {
    const { language } = props;
    const t = translations[language];

    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);
    const [layout, setLayout] = useState<string[]>([]);
    const [viewingProject, setViewingProject] = useState<ProjectWithMilestones | null>(null);
    const [viewingTeamProjects, setViewingTeamProjects] = useState<{ team: Lookup; projects: Project[] } | null>(null);

    useEffect(() => {
        try {
            const savedLayout = localStorage.getItem('dashboardLayout');
            if (savedLayout) {
                const parsedLayout = JSON.parse(savedLayout);
                const validWidgetIds = new Set(WIDGETS_CONFIG.map(w => w.id));
                const filteredLayout = parsedLayout.filter((id: string) => validWidgetIds.has(id));
                setLayout(filteredLayout);
            } else {
                setLayout(WIDGETS_CONFIG.filter(w => w.default).map(w => w.id));
            }
        } catch (error) {
            console.error("Failed to load dashboard layout", error);
            setLayout(WIDGETS_CONFIG.filter(w => w.default).map(w => w.id));
        }
    }, []);

    const handleSaveLayout = (newLayout: string[]) => {
        setLayout(newLayout);
        localStorage.setItem('dashboardLayout', JSON.stringify(newLayout));
        setIsCustomizeModalOpen(false);
    };

    const renderedWidgets = useMemo(() => {
        return layout.map(widgetId => {
            const widget = WIDGETS_CONFIG.find(w => w.id === widgetId);
            if (!widget) return null;
            const Component = widget.component as React.FC<any>; // Cast to allow custom callbacks
            const colSpan = widget.colSpan;
            const colSpanClass = `lg:col-span-${colSpan}`;

            return (
                <div key={widget.id} className={colSpanClass}>
                  <Component 
                    {...props} 
                    onViewProjectDetails={setViewingProject} 
                    onTeamClick={(team: Lookup, teamProjects: Project[]) => setViewingTeamProjects({ team, projects: teamProjects })} 
                  />
                </div>
            );
        });
    }, [layout, props]);

    return (
        <div className="space-y-8">
             {isCustomizeModalOpen && (
                <CustomizeDashboardModal
                    isOpen={isCustomizeModalOpen}
                    onClose={() => setIsCustomizeModalOpen(false)}
                    currentLayout={layout}
                    onSaveLayout={handleSaveLayout}
                    language={language}
                />
            )}
            {viewingProject && (
                <ProjectDetailModal
                    projectWithMilestones={viewingProject}
                    onClose={() => setViewingProject(null)}
                    language={language}
                />
            )}
            {viewingTeamProjects && (
                <TeamProjectsModal
                    team={viewingTeamProjects.team}
                    projects={viewingTeamProjects.projects}
                    onClose={() => setViewingTeamProjects(null)}
                    language={language}
                    onViewProject={(p) => {
                        setViewingTeamProjects(null);
                        // Find the project with its milestones to pass to ProjectDetailModal
                        const projectWithMilestones: ProjectWithMilestones = {
                            ...p,
                            milestones: props.milestones.filter(a => a.projectId === p.id)
                        };
                        setViewingProject(projectWithMilestones);
                    }}
                />
            )}
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900 dark:text-white">{t.dashboard}</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">{t.overview}</p>
                </div>
                <button onClick={() => setIsCustomizeModalOpen(true)} className="bg-slate-200 dark:bg-slate-700/50 hover:bg-slate-300 dark:hover:bg-slate-600/50 text-slate-800 dark:text-white font-bold py-2 px-4 rounded-full flex items-center gap-2 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a1 1 0 00-2 0v7.268a2 2 0 000 3.464V16a1 1 0 102 0v-1.268a2 2 0 000-3.464V4zM11 4a1 1 0 10-2 0v1.268a2 2 0 000 3.464V16a1 1 0 102 0V8.732a2 2 0 00-3.464V4zM16 3a1 1 0 011 1v7.268a2 2 0 010 3.464V16a1 1 0 11-2 0v-1.268a2 2 0 010-3.464V4a1 1 0 011-1z" /></svg>
                    <span>{t.customize}</span>
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                {renderedWidgets}
            </div>
        </div>
    );
};

export default AnalyticsDashboard;

