import React, { useState, useRef, useEffect } from 'react';
import { Milestone, Project, Lookup, Language, MilestoneStatus, PaymentStatus } from '../types';

interface MilestoneListItemProps {
    milestone: Milestone;
    project?: Project;
    team?: Lookup;
    language: Language;
    onOpenEditModal: () => void;
    onDoubleClick: () => void;
    onUpdateMilestone: (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>) => Promise<void>;
}

const MilestoneListItem: React.FC<MilestoneListItemProps> = ({ milestone, project, team, language, onOpenEditModal, onDoubleClick, onUpdateMilestone }) => {
    const [paymentMenuOpen, setPaymentMenuOpen] = useState(false);
    const paymentMenuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (paymentMenuRef.current && !paymentMenuRef.current.contains(event.target as Node)) setPaymentMenuOpen(false);
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const statusColors: { [key in MilestoneStatus]: string } = {
        [MilestoneStatus.Completed]: 'bg-green-500/10 text-green-600 dark:text-green-400',
        [MilestoneStatus.InProgress]: 'bg-blue-500/10 text-blue-600 dark:text-blue-400',
        [MilestoneStatus.Pending]: 'bg-slate-500/10 text-slate-600 dark:text-slate-400',
    };

    const paymentStatusColors: { [key in PaymentStatus]: string } = {
        [PaymentStatus.Paid]: 'bg-green-500/10 text-green-600 dark:text-green-400',
        [PaymentStatus.Sent]: 'bg-blue-500/10 text-blue-600 dark:text-blue-400',
        [PaymentStatus.Pending]: 'bg-yellow-500/10 text-yellow-700 dark:text-yellow-300',
    };

    const translations = {
        ar: { edit: "تعديل", options: "خيارات المعلم", Pending: "معلقة", Sent: "مرسلة", Paid: "مدفوعة", noDueDate: "لا يوجد تاريخ", unassigned: "غير معين" },
        en: { edit: "Edit", options: "Milestone options", Pending: "Pending", Sent: "Sent", Paid: "Paid", noDueDate: "No date", unassigned: "Unassigned" },
    };
    const t = translations[language];

    const isValidDate = milestone.dueDate && !isNaN(new Date(milestone.dueDate).getTime());
    const dueDate = isValidDate ? new Date(milestone.dueDate) : null;
    const isOverdue = dueDate && dueDate < new Date() && milestone.status !== MilestoneStatus.Completed;

    const handlePaymentStatusChange = (newStatus: PaymentStatus) => {
        onUpdateMilestone(milestone.id, { paymentStatus: newStatus });
        setPaymentMenuOpen(false);
    };

    return (
        <div 
            onDoubleClick={onDoubleClick}
            className="bg-white dark:bg-slate-900/30 backdrop-blur-xl border border-slate-200 dark:border-slate-700/50 p-3 rounded-lg flex items-center gap-4 hover:border-violet-400 dark:hover:border-violet-500/80 transition-all duration-300 text-sm cursor-pointer hover:shadow-md"
        >
            <div className="flex-1 min-w-0">
                <p className="font-bold text-slate-800 dark:text-white truncate">{milestone.title}</p>
                <p className="text-xs text-slate-500 dark:text-slate-400 truncate">{milestone.description}</p>
            </div>

            <div className="w-40 text-center shrink-0 flex items-center justify-center gap-2">
                {milestone.hasPayment && (
                    <>
                        <span className="text-green-600 dark:text-green-400 font-mono text-xs">{milestone.paymentAmount.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD' })}</span>
                        <div className="relative" ref={paymentMenuRef}>
                            <button onClick={(e) => { e.stopPropagation(); setPaymentMenuOpen(p => !p); }} className={`flex items-center gap-1 text-xs font-bold px-2 py-1 rounded-full cursor-pointer ${paymentStatusColors[milestone.paymentStatus || PaymentStatus.Pending]}`}>
                                {t[milestone.paymentStatus || PaymentStatus.Pending]}
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                            </button>
                            {paymentMenuOpen && (
                                <div className="absolute top-full right-0 rtl:left-0 rtl:right-auto mt-1 w-32 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg shadow-lg z-20">
                                    {Object.values(PaymentStatus).map(status => (
                                        <button key={status} onClick={(e) => {e.stopPropagation(); handlePaymentStatusChange(status)}} className="w-full text-start px-3 py-1.5 text-xs text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700">{t[status]}</button>
                                    ))}
                                </div>
                            )}
                        </div>
                    </>
                )}
            </div>

            <div className="w-32 text-center shrink-0">
                <span className={`px-2.5 py-1 text-xs font-semibold rounded-full ${statusColors[milestone.status]}`}>{milestone.status}</span>
            </div>

            <div className="w-40 text-center shrink-0 font-medium text-slate-600 dark:text-slate-300 truncate">
                {team?.name || t.unassigned}
            </div>

            <div className={`w-28 text-center shrink-0 font-medium ${isOverdue ? 'text-red-500' : 'text-slate-600 dark:text-slate-300'}`}>
                {dueDate ? dueDate.toLocaleDateString(language === 'ar' ? 'ar-EG' : 'en-US') : t.noDueDate}
            </div>

            <div className="shrink-0">
                <button 
                    onClick={(e) => { e.stopPropagation(); onOpenEditModal(); }} 
                    className="px-4 py-1.5 text-xs font-bold text-violet-700 dark:text-violet-300 bg-violet-100 dark:bg-violet-500/20 rounded-full hover:bg-violet-200 dark:hover:bg-violet-500/30 transition-colors"
                >
                    {t.edit}
                </button>
            </div>
        </div>
    );
};

export default MilestoneListItem;

import React, { useState, useMemo } from 'react';
import { Milestone, Project, Lookup, MilestoneStatus, Language, PaymentStatus } from '../types';
import SearchableSelect from './SearchableSelect';

interface AddMilestoneModalProps {
  teams: Lookup[];
  projects: Project[];
  onClose: () => void;
  onAddMilestone: (newMilestone: Omit<Milestone, 'id'>) => void;
  language: Language;
}

const AddMilestoneModal: React.FC<AddMilestoneModalProps> = ({ teams, projects, onClose, onAddMilestone, language }) => {
  const [formData, setFormData] = useState({
      title: '',
      description: '',
      projectId: '',
      teamId: '',
      dueDate: '',
      status: MilestoneStatus.Pending,
      hasPayment: false,
      paymentAmount: 0,
  });
  const [error, setError] = useState<string | null>(null);

  const canAdd = projects.length > 0 && teams.length > 0;

  const translations = {
      ar: {
          title: "إضافة معلم جديد",
          milestoneTitle: "اسم المعلم",
          description: "الوصف",
          project: "المشروع",
          team: "الفريق المسؤول",
          dueDate: "تاريخ الاستحقاق",
          status: "الحالة",
          hasPayment: "عليه دفعة",
          paymentAmount: "مبلغ الدفعة",
          add: "إضافة معلم",
          cancel: "إلغاء",
          validationError: "يجب إنشاء مشروع وفريق أولاً قبل إضافة المعالم.",
          validationErrorFields: "يرجى ملء جميع الحقول المطلوبة (العنوان، المشروع، الفريق).",
          selectHere: "اختر من هنا...",
          searchProject: "ابحث عن مشروع...",
      },
      en: {
          title: "Add New Milestone",
          milestoneTitle: "Milestone Title",
          description: "Description",
          project: "Project",
          team: "Assigned Team",
          dueDate: "Due Date",
          status: "Status",
          hasPayment: "Has Payment",
          paymentAmount: "Payment Amount",
          add: "Add Milestone",
          cancel: "Cancel",
          validationError: "A project and a team must be created before adding milestones.",
          validationErrorFields: "Please fill all required fields (Title, Project, Team).",
          selectHere: "Select from here...",
          searchProject: "Search for a project...",
      },
  };
  const t = translations[language];

  const projectOptions = useMemo(() => 
    projects.map(p => ({ value: p.id, label: p.name })),
    [projects]
  );

  const handleProjectChange = (projectId: string) => {
      setFormData(prev => ({...prev, projectId: projectId}));
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') {
      setFormData(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (!canAdd) {
        setError(t.validationError);
        return;
    }

    if (!formData.title || !formData.projectId || !formData.teamId) {
        setError(t.validationErrorFields);
        return;
    }

    const newMilestoneData: Omit<Milestone, 'id'> = {
      ...formData,
      dueDate: formData.dueDate ? new Date(formData.dueDate).toISOString() : null,
      paymentAmount: formData.hasPayment ? formData.paymentAmount : 0,
      paymentStatus: formData.hasPayment ? PaymentStatus.Pending : null,
    };
    onAddMilestone(newMilestoneData);
  };

  const inputClasses = "w-full p-3 bg-slate-100 dark:bg-slate-800/50 rounded-lg border border-slate-300 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-violet-500 text-slate-800 dark:text-white placeholder-slate-400 dark:placeholder-slate-500";
  const selectClasses = "w-full p-3 bg-slate-100 dark:bg-slate-800/50 rounded-lg border border-slate-300 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-violet-500 text-slate-800 dark:text-white";

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 backdrop-blur-sm flex items-center justify-center z-50 transition-opacity">
      <div className="bg-white dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-700/50 p-2 rounded-2xl shadow-2xl w-full max-w-lg m-4" dir={language === 'ar' ? 'rtl' : 'ltr'}>
        <div className="p-6 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center border-b border-slate-200 dark:border-slate-700 pb-4 mb-6">
                <h2 className="text-2xl font-bold text-slate-800 dark:text-white">{t.title}</h2>
                <button onClick={onClose} className="text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-white">&times;</button>
            </div>

            {error && <div className="p-3 mb-4 text-sm text-red-800 dark:text-red-200 bg-red-100 dark:bg-red-500/20 rounded-lg" role="alert">{error}</div>}

            {!canAdd ? (
                 <div className="p-4 text-sm text-center text-yellow-800 dark:text-yellow-200 bg-yellow-100 dark:bg-yellow-500/20 rounded-lg">{t.validationError}</div>
            ) : (
                <form onSubmit={handleSubmit} className="space-y-4">
                  <div>
                      <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.milestoneTitle}</label>
                      <input type="text" name="title" value={formData.title} onChange={handleChange} required className={inputClasses}/>
                  </div>
                  <div>
                      <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.description}</label>
                      <textarea name="description" value={formData.description} onChange={handleChange} rows={3} className={inputClasses}/>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                          <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.project}</label>
                           <SearchableSelect
                            options={projectOptions}
                            value={formData.projectId}
                            onChange={handleProjectChange}
                            placeholder={t.selectHere}
                            searchPlaceholder={t.searchProject}
                            language={language}
                          />
                      </div>
                      <div>
                          <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.team}</label>
                          <select name="teamId" value={formData.teamId} onChange={handleChange} required className={selectClasses}>
                              <option value="" disabled>{t.selectHere}</option>
                              {teams.map(t => (<option key={t.id} value={t.id}>{t.name}</option>))}
                          </select>
                      </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.dueDate}</label>
                      <input type="date" name="dueDate" value={formData.dueDate} onChange={handleChange} className={inputClasses} />
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.status}</label>
                        <select name="status" value={formData.status} onChange={handleChange} required className={selectClasses}>
                            {Object.values(MilestoneStatus).sort().map(s => (<option key={s} value={s}>{s}</option>))}
                        </select>
                    </div>
                  </div>

                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">
                        <div className="flex items-center pt-5">
                          <input id="has_payment" name="hasPayment" type="checkbox" checked={formData.hasPayment} onChange={handleChange} className="w-4 h-4 text-violet-600 bg-slate-200 dark:bg-slate-700 border-slate-300 dark:border-slate-600 rounded focus:ring-violet-500" />
                          <label htmlFor="has_payment" className="ms-2 text-sm font-medium text-slate-600 dark:text-slate-300">{t.hasPayment}</label>
                        </div>
                       {formData.hasPayment && (
                            <div>
                                <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.paymentAmount}</label>
                                <input type="number" name="paymentAmount" value={formData.paymentAmount} onChange={(e) => setFormData(p => ({...p, paymentAmount: parseFloat(e.target.value) || 0}))} className={inputClasses} min="0" />
                            </div>
                        )}
                   </div>

                  <div className="flex justify-end space-x-4 rtl:space-x-reverse pt-6 border-t border-slate-200 dark:border-slate-700 mt-6">
                      <button type="button" onClick={onClose} className="px-5 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-200 dark:bg-slate-700/80 rounded-lg hover:bg-slate-300 dark:hover:bg-slate-600/80 transition-colors">{t.cancel}</button>
                      <button type="submit" disabled={!canAdd} className="px-5 py-3 text-sm font-bold text-white bg-gradient-to-r from-violet-600 to-indigo-600 rounded-lg hover:opacity-90 transition-opacity disabled:opacity-50 disabled:cursor-not-allowed">{t.add}</button>
                  </div>
                </form>
            )}
        </div>
      </div>
    </div>
  );
};

export default AddMilestoneModal;

import React, { useState, useEffect } from 'react';
import { Milestone, Project, Lookup, MilestoneStatus, Language, PaymentStatus, MilestoneUpdate, User } from '../types';

interface EditMilestoneModalProps {
  milestoneToEdit: Milestone;
  teams: Lookup[];
  projects: Project[];
  allMilestoneUpdates: MilestoneUpdate[];
  allUsers: User[];
  currentUser?: User;
  onClose: () => void;
  onUpdateMilestone: (milestoneId: string, updatedData: Partial<Omit<Milestone, 'id'>>) => Promise<void>;
  onAddUpdate: (updateData: Omit<MilestoneUpdate, 'id' | 'createdAt' | 'user'>) => Promise<void>;
  language: Language;
}

const EditMilestoneModal: React.FC<EditMilestoneModalProps> = ({ milestoneToEdit, teams, projects, allMilestoneUpdates, allUsers, currentUser, onClose, onUpdateMilestone, onAddUpdate, language }) => {
    const [formData, setFormData] = useState<Omit<Milestone, 'id'>>({
        title: '', description: '', projectId: '', teamId: '', dueDate: '',
        status: MilestoneStatus.Pending, hasPayment: false, paymentAmount: 0, paymentStatus: PaymentStatus.Pending,
    });
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [isSuccess, setIsSuccess] = useState(false);
    const [newUpdateText, setNewUpdateText] = useState('');

    useEffect(() => {
        if (milestoneToEdit) {
            const isValidDate = milestoneToEdit.dueDate && !isNaN(new Date(milestoneToEdit.dueDate).getTime());
            setFormData({
                title: milestoneToEdit.title,
                description: milestoneToEdit.description,
                projectId: milestoneToEdit.projectId || '',
                teamId: milestoneToEdit.teamId || '',
                dueDate: isValidDate ? new Date(milestoneToEdit.dueDate).toISOString().split('T')[0] : '',
                status: milestoneToEdit.status,
                hasPayment: milestoneToEdit.hasPayment,
                paymentAmount: milestoneToEdit.paymentAmount,
                paymentStatus: milestoneToEdit.paymentStatus || PaymentStatus.Pending,
            });
        }
    }, [milestoneToEdit, projects, teams]);

    const translations = {
      ar: {
          title: "تعديل المعلم", milestoneTitle: "اسم المعلم", description: "الوصف", project: "المشروع", team: "الفريق المسؤول", dueDate: "تاريخ الاستحقاق", status: "الحالة", hasPayment: "عليه دفعة", paymentAmount: "مبلغ الدفعة", paymentStatus: "حالة الدفع", update: "تحديث المعلم", cancel: "إلغاء", Pending: "معلقة", Sent: "مرسلة", Paid: "مدفوعة", submitting: "جاري التحديث...", validationError: "يرجى ملء جميع الحقول المطلوبة.", successMessage: "تم التحديث بنجاح!",
          updatesTitle: "سجل التحديثات", noUpdates: "لا توجد تحديثات لهذا المعلم بعد.", addUpdatePlaceholder: "أضف تحديثًا...", post: "نشر",
          selectHere: "اختر من هنا...",
      },
      en: {
          title: "Edit Milestone", milestoneTitle: "Milestone Title", description: "Description", project: "Project", team: "Assigned Team", dueDate: "Due Date", status: "Status", hasPayment: "Has Payment", paymentAmount: "Payment Amount", paymentStatus: "Payment Status", update: "Update Milestone", cancel: "Cancel", Pending: "Pending", Sent: "Sent", Paid: "Paid", submitting: "Updating...", validationError: "Please fill all required fields.", successMessage: "Updated successfully!",
          updatesTitle: "Milestone Updates", noUpdates: "No updates for this milestone yet.", addUpdatePlaceholder: "Add an update...", post: "Post",
          selectHere: "Select from here...",
      },
  };
  const t = translations[language];

  const milestoneUpdates = allMilestoneUpdates.filter(u => u.milestoneId === milestoneToEdit.id);
  const getUserById = (id: string) => allUsers.find(u => u.id === id);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
      const { name, value, type } = e.target;
      if (type === 'checkbox') {
          setFormData(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
      } else {
          setFormData(prev => ({ ...prev, [name]: value }));
      }
  };

  const handleAddUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUpdateText.trim() || !currentUser) return;
    onAddUpdate({
        milestoneId: milestoneToEdit.id,
        userId: currentUser.id,
        updateText: newUpdateText,
    });
    setNewUpdateText('');
  };


  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsSuccess(false);

    if (!formData.title || !formData.projectId || !formData.teamId) {
        setError(t.validationError);
        return;
    }

    setIsSubmitting(true);
    const updatedData: Partial<Omit<Milestone, 'id'>> = {
      ...formData,
      dueDate: formData.dueDate ? new Date(formData.dueDate).toISOString() : null,
      paymentAmount: formData.hasPayment ? formData.paymentAmount : 0,
      paymentStatus: formData.hasPayment ? formData.paymentStatus : null,
    };

    try {
        await onUpdateMilestone(milestoneToEdit.id, updatedData);
        setIsSuccess(true);
        setTimeout(() => onClose(), 1000);
    } catch (err: any) {
        setError(err?.message || "An unknown error occurred.");
    } finally {
        setIsSubmitting(false);
    }
  };

  const inputClasses = "w-full p-3 bg-slate-100 dark:bg-slate-800/50 rounded-lg border border-slate-300 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-violet-500 text-slate-800 dark:text-white";
  const selectClasses = "w-full p-3 bg-slate-100 dark:bg-slate-800/50 rounded-lg border border-slate-300 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-violet-500 text-slate-800 dark:text-white";

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 backdrop-blur-sm flex items-center justify-center z-50 transition-opacity">
      <div className="bg-white dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-700/50 p-2 rounded-2xl shadow-2xl w-full max-w-lg m-4" dir={language === 'ar' ? 'rtl' : 'ltr'}>
        <div className="p-6 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center border-b border-slate-200 dark:border-slate-700 pb-4 mb-6">
                <h2 className="text-2xl font-bold text-slate-800 dark:text-white">{t.title}</h2>
                <button onClick={onClose} className="text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white">&times;</button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                  <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.milestoneTitle}</label>
                  <input type="text" name="title" value={formData.title} onChange={handleChange} required className={inputClasses}/>
              </div>
              <div>
                  <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.description}</label>
                  <textarea name="description" value={formData.description} onChange={handleChange} rows={3} className={inputClasses}/>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                      <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.project}</label>
                      <select name="projectId" value={formData.projectId} onChange={handleChange} required className={selectClasses}>
                          <option value="" disabled>{t.selectHere}</option>
                          {projects.map(p => (<option key={p.id} value={p.id}>{p.name}</option>))}
                      </select>
                  </div>
                  <div>
                      <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.team}</label>
                      <select name="teamId" value={formData.teamId || ''} onChange={handleChange} required className={selectClasses}>
                          <option value="" disabled>{t.selectHere}</option>
                          {teams.map(u => (<option key={u.id} value={u.id}>{u.name}</option>))}
                      </select>
                  </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.dueDate}</label>
                  <input type="date" name="dueDate" value={formData.dueDate || ''} onChange={handleChange} className={inputClasses} />
                </div>
                 <div>
                    <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.status}</label>
                    <select name="status" value={formData.status} onChange={handleChange} required className={selectClasses}>
                        {Object.values(MilestoneStatus).sort().map(s => (<option key={s} value={s}>{s}</option>))}
                    </select>
                </div>
              </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">
                    <div className="flex items-center pt-5">
                      <input id="hasPayment" name="hasPayment" type="checkbox" checked={formData.hasPayment} onChange={handleChange} className="w-4 h-4 text-violet-600 bg-slate-200 dark:bg-slate-700 border-slate-300 dark:border-slate-600 rounded focus:ring-violet-500" />
                      <label htmlFor="hasPayment" className="ms-2 text-sm font-medium text-slate-600 dark:text-slate-300">{t.hasPayment}</label>
                    </div>
                   {formData.hasPayment && (
                        <div>
                            <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.paymentAmount}</label>
                            <input type="number" name="paymentAmount" value={formData.paymentAmount} onChange={(e) => setFormData(p => ({...p, paymentAmount: parseFloat(e.target.value) || 0}))} className={inputClasses} min="0" />
                        </div>
                    )}
               </div>

                {formData.hasPayment && (
                    <div>
                        <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">{t.paymentStatus}</label>
                        <select name="paymentStatus" value={formData.paymentStatus || ''} onChange={handleChange} required className={selectClasses}>
                            {Object.values(PaymentStatus)
                                .map(s => ({ value: s, label: t[s as keyof typeof t] || s }))
                                .sort((a, b) => a.label.localeCompare(b.label))
                                .map(s => (<option key={s.value} value={s.value}>{s.label}</option>))}
                        </select>
                    </div>
                )}

                {/* Updates Section */}
                <div className="pt-4 mt-4 border-t border-slate-200 dark:border-slate-700">
                    <h4 className="font-bold text-slate-600 dark:text-slate-300 mb-3">{t.updatesTitle}</h4>
                    <div className="space-y-3 max-h-40 overflow-y-auto pr-2 rtl:pl-2 mb-4 border-b border-slate-200 dark:border-slate-700 pb-4">
                        {milestoneUpdates.length > 0 ? milestoneUpdates.map(update => {
                            const user = getUserById(update.userId);
                            return (
                                <div key={update.id} className="flex items-start gap-3">
                                    <img src={user?.avatarUrl || `https://ui-avatars.com/api/?name=${user?.name || '?'}&background=a78bfa&color=f5f3ff`} alt={user?.name || 'User'} className="w-7 h-7 rounded-full mt-1 flex-shrink-0" />
                                    <div>
                                        <p className="text-xs text-slate-500 dark:text-slate-400">
                                            <span className="font-bold text-slate-700 dark:text-slate-200">{user?.name}</span>
                                            <span className="mx-1">&middot;</span>
                                            <span>{new Date(update.createdAt).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' })}</span>
                                        </p>
                                        <p className="text-sm text-slate-800 dark:text-slate-100 whitespace-pre-wrap">{update.updateText}</p>
                                    </div>
                                </div>
                            )
                        }) : (
                             <p className="text-sm text-center text-slate-500 dark:text-slate-400 py-4">{t.noUpdates}</p>
                        )}
                    </div>
                    <div className="flex items-center gap-2">
                        <img src={currentUser?.avatarUrl || `https://ui-avatars.com/api/?name=${currentUser?.name || '?'}&background=8b5cf6&color=f5f3ff`} alt={currentUser?.name} className="w-8 h-8 rounded-full flex-shrink-0" />
                        <input
                            type="text"
                            value={newUpdateText}
                            onChange={(e) => setNewUpdateText(e.target.value)}
                            placeholder={t.addUpdatePlaceholder}
                            className="flex-grow w-full p-2 bg-white dark:bg-slate-900/50 rounded-lg border border-slate-300 dark:border-slate-600 focus:outline-none focus:ring-1 focus:ring-violet-500 text-sm"
                        />
                        <button type="button" onClick={handleAddUpdate} className="px-4 py-2 text-sm font-bold text-white bg-violet-600 rounded-lg hover:bg-violet-700 transition-colors">{t.post}</button>
                    </div>
                </div>

              <div className="flex justify-end items-center space-x-4 rtl:space-x-reverse pt-6 border-t border-slate-200 dark:border-slate-700 mt-6">
                  <div className="flex-grow text-sm">
                      {error && <p className="text-red-600 dark:text-red-400 font-medium">{error}</p>}
                      {isSuccess && <p className="text-green-600 dark:text-green-400 font-medium">{t.successMessage}</p>}
                  </div>
                  <button type="button" onClick={onClose} className="px-5 py-2 font-medium text-slate-700 dark:text-slate-300 bg-slate-200 dark:bg-slate-800/80 rounded-lg hover:bg-slate-300 dark:hover:bg-slate-700/80 transition-colors">{t.cancel}</button>
                  <button type="submit" disabled={isSubmitting || isSuccess} className="px-5 py-3 font-bold text-white bg-gradient-to-r from-violet-600 to-indigo-600 rounded-lg hover:opacity-90 transition-opacity disabled:opacity-50">{isSubmitting ? t.submitting : t.update}</button>
              </div>
            </form>
        </div>
      </div>
    </div>
  );
};

export default EditMilestoneModal;

import React, { useState, useMemo } from 'react';
import { Milestone, Project, Lookup, Language, PaymentStatus, MilestoneStatus, MilestoneUpdate, User, Lookups } from '../types';

interface MilestoneDetailModalProps {
    milestone: Milestone;
    projects: Project[];
    allMilestoneUpdates: MilestoneUpdate[];
    allUsers: User[];
    lookups: Lookups;
    onClose: () => void;
    language: Language;
}

const InfoItem: React.FC<{ label: string; value?: string | null; children?: React.ReactNode }> = ({ label, value, children }) => (
    <div className="bg-slate-100 dark:bg-slate-800/50 p-3 rounded-lg">
        <p className="text-xs text-slate-500 dark:text-slate-400 mb-0.5">{label}</p>
        <div className="text-sm font-semibold text-slate-800 dark:text-white truncate">
            {children || value || '--'}
        </div>
    </div>
);

const MilestoneDetailModal: React.FC<MilestoneDetailModalProps> = ({ milestone, projects, allMilestoneUpdates, allUsers, lookups, onClose, language }) => {
    const t = translations[language];
    const project = projects.find(p => p.id === milestone.projectId);
    const team = lookups.teams.find(t => t.id === milestone.teamId);

    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    const statusColors: { [key in MilestoneStatus]: string } = {
        [MilestoneStatus.Completed]: 'bg-green-500/10 text-green-600 dark:text-green-400',
        [MilestoneStatus.InProgress]: 'bg-blue-500/10 text-blue-600 dark:text-blue-400',
        [MilestoneStatus.Pending]: 'bg-slate-500/10 text-slate-600 dark:text-slate-400',
    };

    const paymentStatusColors: { [key in PaymentStatus]: string } = {
        [PaymentStatus.Paid]: 'bg-green-500/10 text-green-700 dark:text-green-300',
        [PaymentStatus.Sent]: 'bg-blue-500/10 text-blue-700 dark:text-blue-300',
        [PaymentStatus.Pending]: 'bg-yellow-500/10 text-yellow-700 dark:text-yellow-300',
    };

    const formatDate = (dateString: string | null | undefined) => {
        if (!dateString) return '--';
        return new Date(dateString).toLocaleDateString(language === 'ar' ? 'ar-EG' : 'en-US');
    };

    const getUserById = (id: string) => allUsers.find(u => u.id === id);

    const filteredUpdates = useMemo(() => {
        return allMilestoneUpdates
            .filter(update => {
                if (update.milestoneId !== milestone.id) return false;
                const updateDate = new Date(update.createdAt);
                if (startDate && updateDate < new Date(startDate)) return false;
                if (endDate) {
                    const endOfDay = new Date(endDate);
                    endOfDay.setHours(23, 59, 59, 999);
                    if (updateDate > endOfDay) return false;
                }
                return true;
            });
    }, [startDate, endDate, allMilestoneUpdates, milestone.id]);

    const handleExport = () => {
        const printContent = `
            <html dir="${language === 'ar' ? 'rtl' : 'ltr'}">
            <head>
                <title>${t.milestoneReport}: ${milestone.title}</title>
                <style>
                    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; line-height: 1.6; color: #333; }
                    h1, h2 { color: #1e1b4b; border-bottom: 2px solid #c4b5fd; padding-bottom: 5px; }
                    .details { background-color: #f8fafc; padding: 15px; border-radius: 8px; margin-bottom: 20px; }
                    .details-grid { display: grid; grid-template-columns: auto 1fr; gap: 8px 16px; }
                    .details-grid dt { font-weight: bold; color: #4c1d95; }
                    .update { border-bottom: 1px solid #e2e8f0; padding: 10px 0; }
                    .update:last-child { border-bottom: none; }
                    .update-header { font-size: 0.9em; color: #64748b; }
                    .update-user { font-weight: bold; }
                    .update-text { margin-top: 5px; }
                </style>
            </head>
            <body>
                <h1>${t.milestoneReport}: ${milestone.title}</h1>
                <div class="details">
                    <h2>${t.details}</h2>
                    <dl class="details-grid">
                        <dt>${t.project}</dt><dd>${project?.name || t.unassigned}</dd>
                        <dt>${t.status}</dt><dd>${milestone.status}</dd>
                        <dt>${t.dueDate}</dt><dd>${formatDate(milestone.dueDate)}</dd>
                        <dt>${t.team}</dt><dd>${team?.name || t.unassigned}</dd>
                    </dl>
                </div>
                <h2>${t.updatesTitle} (${filteredUpdates.length})</h2>
                ${filteredUpdates.map(update => `
                    <div class="update">
                        <p class="update-header">
                            <span class="update-user">${getUserById(update.userId)?.name || 'Unknown User'}</span> &mdash; 
                            <span>${new Date(update.createdAt).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US')}</span>
                        </p>
                        <p class="update-text">${update.updateText.replace(/\n/g, '<br>')}</p>
                    </div>
                `).join('')}
                ${filteredUpdates.length === 0 ? `<p>${t.noUpdates}</p>` : ''}
            </body>
            </html>
        `;

        const printWindow = window.open('', '_blank');
        if (printWindow) {
            printWindow.document.write(printContent);
            printWindow.document.close();
            printWindow.focus();
            printWindow.print();
        }
    };

    const handleExportExcel = () => {
        if (filteredUpdates.length === 0) return;
        const t_csv = csvTranslations[language];
        const headers = [t_csv.userName, t_csv.date, t_csv.update];

        const escapeCsvCell = (cell: any): string => {
            const cellStr = String(cell === null || cell === undefined ? '' : cell);
            if (cellStr.includes(',') || cellStr.includes('"') || cellStr.includes('\n')) {
                return `"${cellStr.replace(/"/g, '""')}"`;
            }
            return cellStr;
        };

        const rows = filteredUpdates.map(update => {
            const user = getUserById(update.userId);
            return [
                user?.name || 'Unknown User',
                new Date(update.createdAt).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US'),
                update.updateText
            ];
        });

        const csvContent = [
            headers.map(escapeCsvCell).join(','),
            ...rows.map(row => row.map(escapeCsvCell).join(','))
        ].join('\n');

        const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        const url = URL.createObjectURL(blob);
        const safeFilename = milestone.title.replace(/[^a-z0-9]/gi, '_').toLowerCase();
        link.setAttribute('href', url);
        link.setAttribute('download', `${safeFilename}_updates.csv`);
        link.style.visibility = 'hidden';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 backdrop-blur-sm flex items-center justify-center z-50 transition-opacity">
            <div className="bg-white dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-slate-700/50 p-2 rounded-2xl shadow-2xl w-full max-w-3xl m-4" dir={language === 'ar' ? 'rtl' : 'ltr'}>
                <div className="p-6 max-h-[90vh] overflow-y-auto">
                    <div className="flex justify-between items-start border-b border-slate-200 dark:border-slate-700 pb-4 mb-6">
                        <div>
                            <p className="text-sm font-semibold text-violet-600 dark:text-violet-400">{t.inProject}: {project?.name}</p>
                            <h2 className="text-2xl font-bold text-slate-800 dark:text-white">{milestone.title}</h2>
                        </div>
                        <button onClick={onClose} className="text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white">
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                        </button>
                    </div>

                    <div className="space-y-6">
                        <p className="text-sm text-slate-600 dark:text-slate-300 bg-slate-100 dark:bg-slate-800/50 p-4 rounded-lg">{milestone.description || t.noDescription}</p>

                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            <InfoItem label={t.status}>
                                <span className={`px-2 py-1 text-xs font-semibold rounded-full ${statusColors[milestone.status]}`}>{milestone.status}</span>
                            </InfoItem>
                            <InfoItem label={t.team} value={team?.name} />
                            <InfoItem label={t.dueDate} value={formatDate(milestone.dueDate)} />
                            <InfoItem label={t.payment}>
                                {milestone.hasPayment ? (
                                    <div className="flex items-center gap-2">
                                        <span className={`px-2 py-0.5 rounded-full text-xs font-semibold ${paymentStatusColors[milestone.paymentStatus || PaymentStatus.Pending]}`}>
                                            {t[milestone.paymentStatus || PaymentStatus.Pending]}
                                        </span>
                                        <span className="font-mono font-bold text-green-600 dark:text-green-400 text-xs">
                                            {milestone.paymentAmount.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US')}
                                        </span>
                                    </div>
                                ) : (<span>--</span>)}
                            </InfoItem>
                        </div>

                        <div>
                            <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-3">{t.updatesTitle}</h3>
                            <div className="flex flex-wrap gap-4 items-center mb-4 p-4 bg-slate-100 dark:bg-slate-800/50 rounded-lg">
                                <div className="flex-grow flex items-center gap-2">
                                    <label htmlFor="startDate" className="text-sm font-medium text-slate-600 dark:text-slate-300">{t.from}</label>
                                    <input type="date" id="startDate" value={startDate} onChange={e => setStartDate(e.target.value)} className="p-2 bg-white dark:bg-slate-900/50 rounded-md border border-slate-300 dark:border-slate-600 text-sm w-full sm:w-auto"/>
                                </div>
                                <div className="flex-grow flex items-center gap-2">
                                    <label htmlFor="endDate" className="text-sm font-medium text-slate-600 dark:text-slate-300">{t.to}</label>
                                    <input type="date" id="endDate" value={endDate} onChange={e => setEndDate(e.target.value)} className="p-2 bg-white dark:bg-slate-900/50 rounded-md border border-slate-300 dark:border-slate-600 text-sm w-full sm:w-auto"/>
                                </div>
