    if (!newUpdateText.trim() || !currentUser) return;
    onAddUpdate({
        // Fixed: Changed 'activityId' to 'milestoneId'
        milestoneId: activityToEdit.id,
        userId: currentUser.id,
        updateText: newUpdateText,
    });
