    setError(null);
    setIsSuccess(false);

    if (!formData.title || !formData.projectId || !formData.teamId) {
        setError(t.validationError);
        return;
    }

    setIsSubmitting(true);
    // Fixed: Changed 'Activity' to 'Milestone'
    const updatedData: Partial<Omit<Milestone, 'id'>> = {
