const mapMaintenanceContractToDb = (contractData: Partial<Omit<MaintenanceContract, 'id' | 'createdAt' | 'customer'>>) => {
    const { customerId, projectCode, totalAmount, collectedAmount, lostAmount, startDate, endDate, notes, ...rest } = contractData;
