export const updateLookups = async (lookupType: keyof Lookups, newLookups: Lookup[]) => {
    const supabase = getSupabase();
    if (!supabase) throw new Error("Supabase client not initialized");

    const tableNameMap: any = {
        countries: 'countries', categories: 'categories', teams: 'teams',
        products: 'products', projectStatuses: 'project_statuses', customers: 'customers',
    };
    const tableName = tableNameMap[lookupType];
    if (!tableName) throw new Error(`Invalid lookup type: ${lookupType}`);

    // This is a naive sync: delete all and re-insert. 
    // In a production app, you'd use upsert or proper diffing.
    const { error: deleteError } = await supabase.from(tableName).delete().neq('id', 'placeholder'); // Just a hack to delete all
    if (deleteError) throw deleteError;

    const { error: insertError } = await supabase.from(tableName).insert(newLookups);
    if (insertError) throw insertError;
};

